        <rect x="-5" y="-28" width="10" height="4" rx="1.5" fill="#9b59b6" stroke="#5b2c6f" stroke-width="1.5" />
        <rect x="-8.5" y="-1" width="17" height="10" rx="1.5" fill="#fef9e7" stroke="#1b4f72" stroke-width="1" />
        <polygon points="0,1 2.5,6.5 -2.5,6.5" fill="#2980b9" />
        <path d="M -5,-4 L -5,12" stroke="#ffffff" stroke-width="2" stroke-linecap="round" opacity="0.65" />
      </g>
    </g>

    <!-- Juggling Cascade Path (Figure-8) -->
    <path id="juggle-arc"
          d="M 225,255
             C 245,80 355,80 375,255
             C 395,295 345,295 355,255
             C 335,80 265,80 245,255
             C 255,295 205,295 225,255 Z" />
  </defs>

  <style>
    /* Subtle balancing sway of the entire unicycle + rider */
    .rig-sway {
      transform-origin: 300px 510px;
      animation: sway 2.4s ease-in-out infinite;
    }
    @keyframes sway {
      0%, 100% { transform: translateX(-8px) rotate(-1.8deg); }
      50%      { transform: translateX(8px) rotate(1.8deg); }
    }

    /* Ground shadow tracks the sway */
    .ground-shadow {
      transform-origin: 300px 512px;
      animation: shadow-move 2.4s ease-in-out infinite;
    }
    @keyframes shadow-move {
      0%, 100% { transform: translateX(-8px) scaleX(0.96); }
      50%      { transform: translateX(8px) scaleX(1.04); }
    }

    /* Wheel & Crank 360° continuous spin */
    .wheel-spin {
      transform-origin: 300px 455px;
      animation: spin 1.6s linear infinite;
    }
    @keyframes spin {
      from { transform: rotate(0deg); }
      to   { transform: rotate(360deg); }
    }

    /* Counter-rotation to keep pedals level */
    .pedal-level-front {
      animation: counter-spin 1.6s linear infinite;
    }
    .pedal-level-back {
      animation: counter-spin 1.6s linear infinite;
    }
    @keyframes counter-spin {
      from { transform: rotate(0deg); }
      to   { transform: rotate(-360deg); }
    }

    /* Body bounce synced to pedaling (2 steps per wheel revolution) */
    .body-bob {
      transform-origin: 300px 350px;
      animation: bob 0.8s ease-in-out infinite;
    }
    @keyframes bob {
      0%, 100% { transform: translateY(0px) rotate(0deg); }
      50%      { transform: translateY(-5px) rotate(0.8deg); }
    }

    /* Bushy tail counterbalance wave */
    .tail-wave {
      transform-origin: 255px 355px;
      animation: tail 1.2s ease-in-out infinite alternate;
    }
    @keyframes tail {
      0%   { transform: rotate(-6deg); }
      100% { transform: rotate(8deg); }
    }

    /* Snout & tongue cheerful wiggle */
    .head-nod {
      transform-origin: 312px 245px;
      animation: nod 1.2s ease-in-out infinite alternate;
    }
    @keyframes nod {
      0%   { transform: rotate(-2.5deg); }
      100% { transform: rotate(2.5deg); }
    }

    .tongue-flick {
      animation: flick 2.4s ease-in-out infinite;
    }
    @keyframes flick {
      0%, 65%, 100% { transform: scaleX(0.2); opacity: 0; }
      78%           { transform: scaleX(1.15); opacity: 1; }
      88%           { transform: scaleX(0.85); opacity: 1; }
    }

    /* Juggling Arms */
    .arm-left {
      transform-origin: 274px 268px;
      animation: throw-left 0.8s ease-in-out infinite;
    }
    @keyframes throw-left {
      0%, 100% { transform: rotate(12deg); }
      50%      { transform: rotate(-22deg); }
    }

    .arm-right {
      transform-origin: 330px 268px;
      animation: throw-right 0.8s ease-in-out infinite;
    }
    @keyframes throw-right {
      0%, 100% { transform: rotate(22deg); }
      50%      { transform: rotate(-12deg); }
    }

    /* Bottle spinning in the air */
    .bottle-spin-cw {
      animation: bspin 0.8s linear infinite;
    }
    @keyframes bspin {
      from { transform: rotate(0deg); }
      to   { transform: rotate(360deg); }
    }

    /* Passing dust puffs */
    .dust-1 {
      animation: puff1 1.6s ease-out infinite;
    }
    .dust-2 {
      animation: puff2 1.6s ease-out -0.8s infinite;
    }
    @keyframes puff1 {
      0%   { transform: translate(0, 0) scale(0.4); opacity: 0.7; }
      100% { transform: translate(-45px, -12px) scale(1.4); opacity: 0; }
    }
    @keyframes puff2 {
      0%   { transform: translate(0, 0) scale(0.4); opacity: 0.7; }
      100% { transform: translate(-35px, -8px) scale(1.2); opacity: 0; }
    }
  </style>

  <!-- ==================== BACKGROUND ==================== -->
